document.querySelectorAll('[data-lab="G13-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const z=root.dataset.lang==='zh',length=root.querySelector('[data-length]'),foot=root.querySelector('[data-footprint]'),count=root.querySelector('[data-count]'),drawing=root.querySelector('[data-drawing]'),feedback=root.querySelector('[data-feedback]');function update(){const L=Number(length.value),F=Number(foot.value),N=Number(count.value),A=L*L;root.querySelector('[data-length-value]').textContent=L.toFixed(1);root.querySelector('[data-footprint-value]').textContent=F.toFixed(0);const valid=F<A,p=Math.min(F/A,1),w=640*p;drawing.innerHTML=`<rect x="130" y="60" width="640" height="210" fill="#d4e6da" stroke="#527776" stroke-width="3"/><rect x="130" y="60" width="${w}" height="210" fill="#b67853"/><text x="450" y="35" text-anchor="middle" font-size="24">${z?'总投影面积':'Total projected area'}: ${A.toFixed(2)} nm²</text><text x="130" y="310" font-size="22" fill="#995334">${z?'蛋白截面':'Protein footprint'}: ${F.toFixed(2)} nm²</text><text x="130" y="345" font-size="22" fill="#28634a">${z?'余下面积':'Remaining area'}: ${valid?(A-F).toFixed(2):'—'} nm²</text>`;feedback.textContent=valid?(z?`几何算例：总面积按脂质数分摊为 ${(A/N).toFixed(4)} nm²/脂质；扣除指定截面后为 ${((A-F)/N).toFixed(4)} nm²/脂质。N = ${N}，计算对象为一个叶片。`:`Geometrical example: total area per lipid is ${(A/N).toFixed(4)} nm²; subtracting the specified footprint gives ${((A-F)/N).toFixed(4)} nm² per lipid. N = ${N} in one leaflet.`):(z?'指定截面已占满或超过整个膜面。减小蛋白截面或增大盒边长，再计算可用面积。':'The specified footprint fills or exceeds the membrane plane. Reduce the footprint or increase the side length before calculating accessible area.');}length.addEventListener('input',update);foot.addEventListener('input',update);count.addEventListener('change',update);root.querySelector('[data-reset]').addEventListener('click',()=>{length.value='10';foot.value='20';count.value='100';update();});update();});